<script setup>
import {sitePath} from '../../paths.js';

import {computed,defineAsyncComponent,ref,watch,onMounted,onBeforeUnmount} from 'vue';import {chartTypes} from '../catalog.js';import {resolveHeaderConfig} from '../header.js';import HeaderRenderer from '../../studio/HeaderRenderer.vue';import FlipNumber from './FlipNumber.vue';
const FrontendCode=defineAsyncComponent(()=>import('./FrontendCode.vue'));
const AdvancedChart=defineAsyncComponent(()=>import('./AdvancedChart.vue')),SpatialScene=defineAsyncComponent(()=>import('./SpatialScene.vue')),MapScene=defineAsyncComponent(()=>import('./MapScene.vue'));
const props=defineProps({node:Object,rows:Array,theme:Object,playing:Boolean,assets:Object,interactive:Boolean,status:Object});const emit=defineEmits(['action']);const now=ref(new Date());const video=ref();watch(()=>props.playing,playing=>{if(!video.value)return;if(playing)video.value.play().catch(()=>{});else video.value.pause();});let timer;onMounted(()=>{if(props.node.type==='clock')timer=setInterval(()=>{if(!document.hidden)now.value=new Date();},1000);});onBeforeUnmount(()=>clearInterval(timer));
const header=computed(()=>resolveHeaderConfig(props.node,props.theme));
const media=computed(()=>sitePath(props.assets?.[props.node.props.assetId]||props.node.props.url||''));const value=computed(()=>(props.node.data.kind!=='static'||props.node.props.useDataValue)?Number(props.rows?.[0]?.[props.node.data.fields.value])||0:props.node.props.value);const list=computed(()=>props.rows||[]);const visibleRows=computed(()=>Math.min(12,Math.max(1,props.node.props.rows||5)));const rankMax=computed(()=>Math.max(...list.value.map(r=>Number(r[props.node.data.fields.value])||0),1));
const dataPreview=computed(()=>(props.rows||[]).slice(0,2).map(row=>Object.fromEntries(Object.entries(row).slice(0,24).filter(([key,v])=>!/password|token|secret|authorization|cookie|api.?key/i.test(key)&&['string','number','boolean'].includes(typeof v)).map(([k,v])=>[k,typeof v==='string'?v.slice(0,120):v]))));
function action(on,row){if(props.interactive)emit('action',on,row);}
</script>
<template><div :data-data-state="status?.state||(node.data.kind==='static'?'static':'loading')" :data-row-count="rows?.length||0" :data-data-fields="JSON.stringify(Object.keys(rows?.[0]||{}).filter(k=>!/password|token|secret|authorization|cookie|api.?key/i.test(k)).slice(0,30))" :data-data-sample="JSON.stringify(dataPreview)" class="aw-widget-content" :class="['widget-'+node.type,{'is-compact':node.props.compact}]">
 <template v-if="node.props.showTitle"><header class="aw-panel-title"><i></i><strong>{{node.props.title}}</strong><span>{{node.props.panelCode||({command:'LIVE',precision:'SYS',botanical:'FIELD',orbital:'LIVE'}[node.style.skin])||'⌁'}}</span></header><p v-if="node.props.subtitle" class="aw-panel-subtitle">{{node.props.subtitle}}</p></template>
 <AdvancedChart v-if="chartTypes.includes(node.type)" :node="node" :rows="rows" :theme="theme" :playing="playing" @action="(...args)=>emit('action',...args)"/>
 <template v-else-if="node.type==='header'"><HeaderRenderer :config="header" :playing="playing"/></template>
 <template v-else-if="node.type==='number'"><div class="aw-number-caption"><span>{{node.props.prefix||'↗'}}</span>{{node.props.title}}</div><div class="aw-number-value"><FlipNumber :value="value" :decimals="node.props.decimals" :animate="node.props.flip&&playing"/><small>{{node.props.unit}}</small></div><div class="aw-number-bottom"><span class="aw-number-trend">{{node.props.trend>=0?'↗':'↘'}} {{Math.abs(node.props.trend)}}%</span><span>较上一统计周期</span><svg viewBox="0 0 90 24"><path d="M0 20L12 16L22 19L32 10L45 13L55 5L65 9L75 3L90 6" fill="none" stroke="currentColor" stroke-width="1.5"/></svg></div></template>
 <div v-else-if="node.type==='text'" class="aw-text" :style="{textAlign:node.props.align,backgroundImage:node.style.gradient?`linear-gradient(110deg,${node.style.color||theme.text},${node.style.gradientTo})`:undefined}" :class="{'gradient-text':node.style.gradient}">{{node.props.text}}</div>
 <div v-else-if="node.type==='clock'" class="aw-clock"><span>{{now.toLocaleDateString('zh-CN')}}</span><strong>{{now.toLocaleTimeString('en-GB')}}</strong></div>
 <div v-else-if="node.type==='progress'" class="aw-progress"><svg viewBox="0 0 160 160"><circle cx="80" cy="80" r="62" fill="none" stroke="currentColor" opacity=".09" stroke-width="8"/><circle cx="80" cy="80" r="62" fill="none" stroke="var(--aw-accent)" stroke-width="8" stroke-linecap="round" :stroke-dasharray="`${Math.min(100,Math.max(0,value))*3.896} 389.6`" transform="rotate(-90 80 80)"/></svg><div><strong>{{value}}<small>{{node.props.unit}}</small></strong><span>{{node.props.title}}</span></div></div>
 <template v-else-if="['table','ranking'].includes(node.type)"><div class="aw-list-heading"><span>{{node.props.listName||(node.type==='ranking'?'排名 / 名称':'事件名称')}}</span><span>{{node.props.listValue||(node.type==='ranking'?'综合指数':'最新状态')}}</span></div><div class="aw-list-viewport" :class="{'is-scrolling':node.props.autoScroll&&list.length>visibleRows&&playing}" :style="{'--row-count':list.length,'--list-duration':Math.max(5,list.length*node.props.interval)+'s','--visible-rows':visibleRows}"><div class="aw-list-scroll"><template v-for="copy in node.props.autoScroll&&list.length>visibleRows?2:1"><button v-for="(row,i) in list" :key="copy+'-'+i" class="aw-list-row" :aria-hidden="copy===2?true:undefined" :tabindex="copy===2?-1:undefined" @click="action('click',row)" @mouseenter="action('hover',row)"><template v-if="node.type==='ranking'"><b>{{String(i+1).padStart(2,'0')}}</b><div><span>{{row[node.data.fields.name]}}</span><i><em :style="{width:(Number(row[node.data.fields.value])/rankMax*100)+'%'}"></em></i></div><strong>{{row[node.data.fields.value]}}</strong></template><template v-else><span class="aw-list-dot" :class="{'is-warn':String(row.status).includes('待')||String(row.status).includes('中')}"></span><span>{{row[node.data.fields.name]}}</span><small>{{row.status||row[node.data.fields.value]}}</small><time>{{row.time}}</time></template></button></template></div></div></template>
 <FrontendCode v-else-if="node.type==='custom'" :node="node" :rows="rows" :theme="theme" :playing="playing" :interactive="interactive" @action="(...args)=>emit('action',...args)"/>
 <SpatialScene v-else-if="['scene','globe','model'].includes(node.type)" :node="node" :theme="theme" :rows="rows" :playing="playing" :assets="assets" :interactive="interactive" @action="(...args)=>emit('action',...args)"/>
 <MapScene v-else-if="node.type==='map'" :node="node" :theme="theme" :playing="playing" :assets="assets" :interactive="interactive" @action="(...args)=>emit('action',...args)"/>
 <img v-else-if="['image','svg'].includes(node.type)&&media" class="aw-image" :src="media" :alt="node.props.title" draggable="false" :style="{objectFit:node.props.objectFit||'contain'}"/>
 <video ref="video" v-else-if="node.type==='video'&&media" class="aw-video" :src="media" muted loop :autoplay="playing" playsinline :controls="interactive" :style="{objectFit:node.props.objectFit||'cover'}"></video>
 <div v-else-if="['image','video','svg'].includes(node.type)" class="aw-media-placeholder"><span>{{node.type==='video'?'▷':'▧'}}</span><strong>选择{{node.type==='video'?'视频':'图片'}}素材</strong><small>从素材库添加或配置资源地址</small></div>
 <div v-else-if="node.type==='decoration'" class="aw-decoration" :class="[node.props.decoration,{'aw-paused':!playing}]"><template v-if="node.props.decoration==='ring'"><svg viewBox="0 0 200 200"><circle cx="100" cy="100" r="80" fill="none" stroke="currentColor" stroke-width="1" stroke-dasharray="40 12"/><circle cx="100" cy="100" r="62" fill="none" stroke="currentColor" stroke-width="2" stroke-dasharray="60 330"/></svg></template><svg v-else viewBox="0 0 400 40" preserveAspectRatio="none"><path d="M0 20H130L146 8H254L270 20H400" stroke="currentColor" fill="none" opacity=".2"/><path class="aw-flow-path" d="M0 20H130L146 8H254L270 20H400" stroke="currentColor" fill="none" stroke-width="2" stroke-dasharray="32 480"/></svg></div>
 <div v-if="status?.state==='error'" class="aw-data-error" :title="status.message"><span>!</span>{{status.message}}</div>
 </div></template>
